func:
// Clear previous partial reads
flow.set("pvds_part_total", undefined);
flow.set("pvds_part_total_energy", undefined);
flow.set("pvds_part_power", undefined);
flow.set("pvds_part_voltcurr", undefined);
flow.set("pvds_part_daily_energy", undefined);

// Preserve RPC context if present
const isRpc = msg.isRpcRequest === true;
if (isRpc) {
    flow.set("pvds_rpc_context", {
        requestId: msg.rpcRequestId,
        responseTopic: msg.rpcResponseTopic
    });
} else {
    flow.set("pvds_rpc_context", undefined);
}

return msg;

// Read registers 529, 718
// 529: Day PV energy
// 718: PV total power
// These are far apart, read separately

// Read 529 first
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 529,
    quantity: 1
};
msg.readPart = "daily_pv";
return msg;

// Read registers 534-535: Total PV energy (reserved)
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 534,
    quantity: 2
};
return msg;

// Read registers 672-675: PV1-4 input power
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 672,
    quantity: 4
};
return msg;

// Read registers 676-683: DC voltage/current 1-4
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 676,
    quantity: 8
};
return msg;

// Read registers 530-533: Day PV 1-4 energy (reserved)
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 530,
    quantity: 4
};
return msg;

const data = msg.payload;
const address = msg.modbusRequest?.address;
const readPart = msg.readPart;

// Helper: u32 from two words
function u32(low, high) {
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// Determine which part this is
if (address === 529 && readPart === "daily_pv") {
    // Day PV energy
    const dailyPvEnergy = data[0] || 0;
    flow.set("pvds_part_daily_pv", dailyPvEnergy);

    // Now read total power (718)
    msg.payload = {
        fc: 3,
        unitid: 1,
        address: 718,
        quantity: 1
    };
    msg.readPart = "total_power";
    return msg;

} else if (address === 718 && readPart === "total_power") {
    // PV total power
    const totalPower = data[0] || 0;
    flow.set("pvds_part_total_power", totalPower);

    // Mark total complete
    flow.set("pvds_part_total", true);

} else if (address === 534) {
    // Total PV energy (reserved) 534-535
    const totalEnergyLow = data[0] || 0;  // 534
    const totalEnergyHigh = data[1] || 0; // 535
    const totalEnergy = u32(totalEnergyLow, totalEnergyHigh);

    flow.set("pvds_part_total_energy", totalEnergy);

} else if (address === 672) {
    // MPPT Power 672-675
    const pv1Power = data[0] || 0;  // 672
    const pv2Power = data[1] || 0;  // 673
    const pv3Power = data[2] || 0;  // 674
    const pv4Power = data[3] || 0;  // 675

    flow.set("pvds_part_power", {
        pv1Power, pv2Power, pv3Power, pv4Power
    });

} else if (address === 676) {
    // MPPT Voltage/Current 676-683
    const pv1Voltage = data[0] || 0;  // 676
    const pv1Current = data[1] || 0;  // 677
    const pv2Voltage = data[2] || 0;  // 678
    const pv2Current = data[3] || 0;  // 679
    const pv3Voltage = data[4] || 0;  // 680
    const pv3Current = data[5] || 0;  // 681
    const pv4Voltage = data[6] || 0;  // 682
    const pv4Current = data[7] || 0;  // 683

    flow.set("pvds_part_voltcurr", {
        pv1Voltage, pv1Current,
        pv2Voltage, pv2Current,
        pv3Voltage, pv3Current,
        pv4Voltage, pv4Current
    });

} else if (address === 530) {
    // MPPT Daily Energy 530-533 (reserved)
    const pv1DailyEnergy = data[0] || 0;  // 530
    const pv2DailyEnergy = data[1] || 0;  // 531
    const pv3DailyEnergy = data[2] || 0;  // 532
    const pv4DailyEnergy = data[3] || 0;  // 533

    flow.set("pvds_part_daily_energy", {
        pv1DailyEnergy, pv2DailyEnergy, pv3DailyEnergy, pv4DailyEnergy
    });
}

// Check if all parts are ready
const totalReady = flow.get("pvds_part_total");
const totalEnergy = flow.get("pvds_part_total_energy");
const powerPart = flow.get("pvds_part_power");
const voltcurrPart = flow.get("pvds_part_voltcurr");
const dailyEnergyPart = flow.get("pvds_part_daily_energy");

if (!totalReady || totalEnergy === undefined || !powerPart || !voltcurrPart || !dailyEnergyPart) {
    return null;  // Wait for all parts
}

// All parts ready - assemble payload
const dailyPvEnergy = flow.get("pvds_part_daily_pv");
const totalPower = flow.get("pvds_part_total_power");

// Voltage threshold for active detection (e.g., 30V)
const VOLTAGE_THRESHOLD = 30;

// Build telemetry
const telemetry = {
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: "loftty-inverter",

    totalPvPowerW: totalPower,
    todayPvEnergyKWh: Math.round((dailyPvEnergy * 0.1) * 10) / 10,
    totalPvEnergyKWh: totalEnergy === 0 ? null : Math.round((totalEnergy * 0.1) * 10) / 10,

    mppt: [
        {
            pvChannelId: 1,
            isActive: (voltcurrPart.pv1Voltage * 0.1) >= VOLTAGE_THRESHOLD,
            dcVoltageV: Math.round((voltcurrPart.pv1Voltage * 0.1) * 10) / 10,
            dcCurrentA: Math.round((voltcurrPart.pv1Current * 0.1) * 100) / 100,
            inputPowerW: powerPart.pv1Power,
            todayEnergyKWh: dailyEnergyPart.pv1DailyEnergy === 0 ? null : Math.round((dailyEnergyPart.pv1DailyEnergy * 0.1) * 10) / 10
        },
        {
            pvChannelId: 2,
            isActive: (voltcurrPart.pv2Voltage * 0.1) >= VOLTAGE_THRESHOLD,
            dcVoltageV: Math.round((voltcurrPart.pv2Voltage * 0.1) * 10) / 10,
            dcCurrentA: Math.round((voltcurrPart.pv2Current * 0.1) * 100) / 100,
            inputPowerW: powerPart.pv2Power,
            todayEnergyKWh: dailyEnergyPart.pv2DailyEnergy === 0 ? null : Math.round((dailyEnergyPart.pv2DailyEnergy * 0.1) * 10) / 10
        },
        {
            pvChannelId: 3,
            isActive: (voltcurrPart.pv3Voltage * 0.1) >= VOLTAGE_THRESHOLD,
            dcVoltageV: Math.round((voltcurrPart.pv3Voltage * 0.1) * 10) / 10,
            dcCurrentA: Math.round((voltcurrPart.pv3Current * 0.1) * 100) / 100,
            inputPowerW: powerPart.pv3Power,
            todayEnergyKWh: dailyEnergyPart.pv3DailyEnergy === 0 ? null : Math.round((dailyEnergyPart.pv3DailyEnergy * 0.1) * 10) / 10
        },
        {
            pvChannelId: 4,
            isActive: (voltcurrPart.pv4Voltage * 0.1) >= VOLTAGE_THRESHOLD,
            dcVoltageV: Math.round((voltcurrPart.pv4Voltage * 0.1) * 10) / 10,
            dcCurrentA: Math.round((voltcurrPart.pv4Current * 0.1) * 100) / 100,
            inputPowerW: powerPart.pv4Power,
            todayEnergyKWh: dailyEnergyPart.pv4DailyEnergy === 0 ? null : Math.round((dailyEnergyPart.pv4DailyEnergy * 0.1) * 10) / 10
        }
    ]
};

// Clear flow context
flow.set("pvds_part_total", undefined);
flow.set("pvds_part_daily_pv", undefined);
flow.set("pvds_part_total_power", undefined);
flow.set("pvds_part_total_energy", undefined);
flow.set("pvds_part_power", undefined);
flow.set("pvds_part_voltcurr", undefined);
flow.set("pvds_part_daily_energy", undefined);

// Check if RPC
const rpcContext = flow.get("pvds_rpc_context");
if (rpcContext) {
    msg.topic = rpcContext.responseTopic;
    msg.payload = telemetry;
    flow.set("pvds_rpc_context", undefined);
    return [msg, null];  // Send to RPC output only
} else {
    msg.payload = telemetry;
    return [null, msg];  // Send to telemetry output only
}
